import axios from 'axios';
import { generateSignature } from '../signer/signer';
export async function getVideoDetails(videoIdOrUrl) {
    try {
        // Extraer el ID del video si se proporciona una URL
        const videoId = videoIdOrUrl.includes('tiktok.com')
            ? videoIdOrUrl.split('/video/')[1]?.split('?')[0]
            : videoIdOrUrl;
        if (!videoId)
            throw new Error('Invalid video ID or URL');
        const url = `https://www.tiktok.com/video/${videoId}`;
        const sig = await generateSignature(url);
        const res = await axios.get(url, {
            headers: {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
                'Referer': 'https://www.tiktok.com/',
                'x-tt-params': sig,
            },
        });
        const match = res.data.match(/<script id="__UNIVERSAL_DATA_FOR_REHYDRATION__" type="application\/json">(.+?)<\/script>/);
        if (!match)
            throw new Error('Video data not found');
        const json = JSON.parse(match[1]);
        const item = json.props?.pageProps?.itemInfo?.itemStruct;
        if (!item)
            throw new Error('Video details not found');
        const tags = (item.text?.match(/#(\w+)/g) || []).map((t) => t.toLowerCase());
        return {
            id: item.id,
            description: item.text || '',
            playCount: item.stats?.playCount || 0,
            likeCount: item.stats?.diggCount || 0,
            commentCount: item.stats?.commentCount || 0,
            shareCount: item.stats?.shareCount || 0,
            hashtags: tags,
            audio: {
                id: item.music?.id || '',
                title: item.music?.title || '',
                videoCount: item.music?.stats?.videoCount || 0,
            },
        };
    }
    catch (error) {
        throw new Error(`Failed to fetch video details: ${error.message}`);
    }
}
